def L(spec=True, *extra):
    """Library list: spec sheet (if the page has one), the documents named on the page, then the three standard listings."""
    items = ([["Spec sheet", "Product specifications."]] if spec else []) + [list(e) for e in extra] + \
            [["Technical documentation", "Guides and manuals."], ["Training videos", "Video training."], ["Marketing literature", "Sales literature."]]
    n = max(k for k in (3, 4, 6, 9) if k <= len(items))
    return items[:n]
CRED = ("Credential compatibility guide", "Which credentials work with which readers.")
RAW = []   # filled by P(); page dicts are built after PRODUCTS is complete


def P(slug, dmp_path, name, short, kicker, system, image, h, sub, what, bullets, feats, specs, lib, rel, faq, d, blurb, mpn=None, alt=None):
    RAW.append(dict(slug=slug, dmp_path=dmp_path, name=name, short=short, kicker=kicker, system=system, image=image, h=h, sub=sub,
                    what=what, bullets=bullets, feats=feats, specs=specs, lib=lib, rel=rel, faq=faq, d=d, blurb=blurb, mpn=mpn,
                    alt=alt or f"The DMP {name}"))


def IM(slug):
    if slug == "xt75": return IMG + "xt75-1200.png"
    if slug == "7-inch-touchscreen-keypad": return IMG + "keypad-722-1200.png"
    for ext in ("png", "jpg"):
        if os.path.exists(os.path.join(ASSETS, f"p-{slug}-1200.{ext}")): return f"{IMG}p-{slug}-1200.{ext}"
    raise SystemExit("missing image for " + slug)


